INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein hohes Angebot an IT-Dienstleistungen immer die Preise senkt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Preise hängen auch von Qualität ab"}, {"text": "Ja", "correct": false, "because": "Nicht automatisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich Hardware in einem übersättigten Markt kaufe?', 3, '[{"text": "Preis-Leistungs-Verhältnis", "correct": true, "because": "Maximiert Nutzen"}, {"text": "Markenname", "correct": false, "because": "Sekundär bei Vergleich"}, {"text": "Schnellste Lieferung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren nutze ich, um in einem IT-Markt mit viel Angebot zu verhandeln?', 5, '[{"text": "Vergleich von Angeboten", "correct": true, "because": "Findet beste Konditionen"}, {"text": "Lieferantenvielfalt", "correct": true, "because": "Erhöht Druck auf Preise"}, {"text": "Höhere Bandbreite", "correct": false, "because": "Irrelevant für Verhandlungen"}, {"text": "Büroausstattung", "correct": false, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Angebotsüberhang gibt mir mehr Auswahl. b) Er führt immer zu Qualitätsverlust.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Qualität bleibt unabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Software in einem Markt mit vielen Anbietern auswähle?', 4, '[{"text": "Funktionsumfang", "correct": false, "because": "Entscheidend für Nutzen"}, {"text": "Supportqualität", "correct": false, "because": "Wichtig für Betrieb"}, {"text": "Werbekampagnen", "correct": true, "because": "Sekundär bei Entscheidung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein hohes Angebot an Servern immer Rabatte bringt?', 2, '[{"text": "Nein", "correct": true, "because": "Hängt von Nachfrage ab"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich Netzwerkausrüstung in einem Markt mit vielen Anbietern kaufe?', 3, '[{"text": "Kostensenkung", "correct": true, "because": "Nutzt Wettbewerb aus"}, {"text": "Schnellste Installation", "correct": false, "because": "Nicht primär"}, {"text": "Exklusive Modelle", "correct": false, "because": "Weniger relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Markt mit vielen IT-Lieferanten?', 5, '[{"text": "Bessere Preise", "correct": true, "because": "Wettbewerb drückt Kosten"}, {"text": "Mehr Auswahl", "correct": true, "because": "Vielfalt erhöht Optionen"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein direkter Effekt"}, {"text": "Weniger Support", "correct": false, "because": "Support bleibt unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein großer Markt stärkt meine Verhandlungsposition. b) Er garantiert immer Qualität. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Qualität ist nicht garantiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um in einem Markt mit vielen IT-Diensten zu entscheiden?', 4, '[{"text": "Anforderungsanalyse", "correct": false, "because": "Definiert Bedarf"}, {"text": "Vergleichskriterien", "correct": false, "because": "Ermöglicht Auswahl"}, {"text": "Lieferantenimage", "correct": true, "because": "Sekundär bei Leistung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Fördert ein hohes Angebot immer Innovation?', 2, '[{"text": "Nein", "correct": true, "because": "Innovation hängt von Anbietern ab"}, {"text": "Ja", "correct": false, "because": "Nicht automatisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte helfen mir, in einem Markt mit vielen Cloud-Anbietern zu wählen?', 4, '[{"text": "Sicherheitsprüfung", "correct": true, "because": "Schützt Daten"}, {"text": "Skalierbarkeit testen", "correct": true, "because": "Sichert Flexibilität"}, {"text": "Bürolayout", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein großer IT-Markt immer die besten Produkte liefert. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Qualität variiert"}, {"text": "Ja", "correct": false, "because": "Keine Garantie"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um in einem Markt mit vielen Laptops das beste Angebot zu finden?', 3, '[{"text": "Vergleichsportale", "correct": true, "because": "Bietet Preisübersicht"}, {"text": "Teuerste Marke", "correct": false, "because": "Nicht immer optimal"}, {"text": "Zufallsauswahl", "correct": false, "because": "Riskant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein hohes Angebot senkt oft Preise. b) Es führt immer zu längeren Lieferzeiten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Lieferzeiten sind unabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei der Auswahl eines IT-Dienstes in einem großen Markt?', 5, '[{"text": "Kostenstruktur", "correct": true, "because": "Beeinflusst Budget"}, {"text": "Vertragsflexibilität", "correct": true, "because": "Ermöglicht Anpassung"}, {"text": "Bürogröße", "correct": false, "because": "Kein Einfluss"}, {"text": "Marketingbudget", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich in einem Markt mit vielen IT-Lösungen entscheide?', 3, '[{"text": "Kompatibilität", "correct": false, "because": "Sichert Integration"}, {"text": "Skalierbarkeit", "correct": false, "because": "Wichtig für Wachstum"}, {"text": "Anbietergröße", "correct": true, "because": "Leistung zählt mehr"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Bedeutet ein großer Markt immer mehr Support?', 3, '[{"text": "Nein", "correct": true, "because": "Support hängt vom Anbieter ab"}, {"text": "Ja", "correct": false, "because": "Keine Garantie"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein hohes Angebot immer schnelleren Service bringt?', 2, '[{"text": "Nein", "correct": true, "because": "Service variiert"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium ist entscheidend, wenn ich in einem Markt mit vielen IT-Produkten kaufe?', 4, '[{"text": "Anforderungserfüllung", "correct": true, "because": "Sichert Nutzen"}, {"text": "Höchster Preis", "correct": false, "because": "Nicht zielführend"}, {"text": "Beste Werbung", "correct": false, "because": "Irrelevant"}]');
